ControlPropertyState.AutoRuleBindingString:
Refresh('SWB Main Issue Tracker');
UpdateContext({ CurrentItem: Self.LastSubmit, editMode: false, newMode: false });
ViewForm(Form1);
Notify("Ticket succesfully created!", NotificationType.Success)

UpdateContext({ 
    CurrentItem: ThisItem, 
    newMode: false, 
    editMode: false 
});
ViewForm(Form1);

If(
    varUserRole = "export" And ThisItem.Status.Value = "New",
    
    Patch(
        'SWB Main Issue Tracker', 
        ThisItem, 
        {Status: {Value: "Open"}}
    )
);

Select(Parent);

ResetForm(Form1);
UpdateContext({ 
    editMode: false, 
    newMode: false, 
    CurrentItem: Blank() 
});
